"""024 no portal: alfabetização, Comunicação compatível e vagas publicadas."""
import unittest
import test_event_planning_browser as events
import test_schedule_edit_window_browser as window_tests
import test_frontend_access as base
class SchedulePublicationRulesBrowserTests(unittest.TestCase):
 setUpClass=classmethod(events.EventPlanningBrowserTests.setUpClass.__func__);tearDownClass=classmethod(events.EventPlanningBrowserTests.tearDownClass.__func__)
 setUp=window_tests.ScheduleEditWindowBrowserTests.setUp;tearDown=window_tests.ScheduleEditWindowBrowserTests.tearDown
 go=window_tests.ScheduleEditWindowBrowserTests.go;choose=window_tests.ScheduleEditWindowBrowserTests.choose;login=window_tests.ScheduleEditWindowBrowserTests.login;department=window_tests.ScheduleEditWindowBrowserTests.department;sign_in=window_tests.ScheduleEditWindowBrowserTests.sign_in;sound=window_tests.ScheduleEditWindowBrowserTests.sound
 def publish(self):
  self.page.once('dialog',lambda d:d.accept());self.page.locator('[data-b1-action=publish]').click();self.page.wait_for_function("()=>document.querySelector('#b1-feedback')?.textContent.includes('Escala publicada')")
 def calendar(self):
  self.go('schedule-calendar');self.page.wait_for_selector('.scale-calendar');self.page.evaluate("()=>{IASDPIScheduleCalendar.show({month:'2026-11'});render();}");self.page.wait_for_function("()=>!document.querySelector('.portal-feed-state')?.textContent.includes('Carregando')")
 def test_single_and_multiple_person_lists_are_alphabetical(self):
  self.sound();names=self.page.locator('[data-calendar-volunteer]').first.locator('option:not([value=""])').all_text_contents();self.assertEqual(names,['Gabriel Macedo','Luan Vaz','Lucas Borrego','Paulo Scarpelini','Rafael Braga','Raphael Moreira','Samuel Ferreira'])
  self.department('Música');self.page.locator('.music-picker').first.locator('summary').click();names=self.page.locator('.music-picker').first.locator('.music-person label>span').all_text_contents();self.assertEqual(names,['Alexandre','Ana Julia','Gislaine','Hélder','Henrique Franco','Izabelle Souza','Laura','Letícia Ferreira','Luisa','Samuel Ferreira','Sol','Victória Scarpelini','Weslley'])
  table=self.page.locator('.schedule-distribution tbody th').all_text_contents();self.assertEqual(table,names)
 def test_calendar_sorts_people_across_departments_and_preserves_selected_ids(self):
  self.sound();self.department('Música');picker=self.page.locator('.monthly-cell:has([data-day="2026-11-07"]) .music-picker');picker.locator('summary').click()
  ids=self.page.evaluate("async()=>{const c=await IASDPISchedules.request('iasdpi_schedule_catalog');return ['Hélder','Gislaine'].map(name=>c.people.find(p=>p.display_name===name).id);}")
  for value in ids:self.page.locator('.monthly-cell:has([data-day="2026-11-07"]) [data-music-volunteer][value="'+value+'"]').check()
  self.publish();self.department('Comunicação');field=self.page.locator('.monthly-cell:has([data-day="2026-11-07"]) select');field.select_option(field.locator('option').filter(has_text='Henrique Franco').get_attribute('value'));self.publish();self.calendar()
  self.page.wait_for_function("()=>document.querySelector('td[data-scale-day=\"2026-11-07\"]')?.textContent.includes('Henrique Franco')")
  labels=self.page.locator('td[data-scale-day="2026-11-07"] .scale-chip').evaluate_all("es=>es.map(e=>{const c=e.cloneNode(true);c.querySelectorAll('.sr-only,svg').forEach(x=>x.remove());return c.textContent;})");self.assertEqual([s.strip() for s in labels],['Gislaine','Hélder','Henrique Franco'])
  for width,label in [(1440,'desktop'),(390,'mobile')]:
   self.page.set_viewport_size({'width':width,'height':1000});self.assertLessEqual(self.page.evaluate('document.documentElement.scrollWidth'),width);self.page.screenshot(path=str(base.ROOT/'dist/schedule-rules-024'/('calendario-'+label+'.png')))
 def test_publish_with_all_vacancies_shows_a_definir_only_to_authorized_view(self):
  self.sound();self.publish();self.calendar();self.page.wait_for_function("()=>IASDPIPortalAccess.feedRows('2026-11').some(r=>r.department==='Sonoplastia'&&r.pending)")
  self.assertIn('A definir',self.page.locator('td[data-scale-day="2026-11-07"]').inner_text())
  result=self.page.evaluate("async()=>{const r=await fetch('https://g4demo.supabase.co/rest/v1/rpc/iasdpi_schedule_published',{method:'POST',headers:{'Content-Type':'application/json','x-iasdpi-church':'IASD_PI'},body:JSON.stringify({p_month:'2026-11-01'})});return r.json();}");self.assertFalse(any(r['department']=='Sonoplastia' for r in result))
 def test_draft_with_pending_is_not_published_and_later_publication_is_visible(self):
  self.sound();self.page.locator('[data-b1-action=save]').click();self.page.wait_for_function("()=>document.querySelector('#b1-feedback')?.textContent.includes('salvas nesta aba')");self.calendar();self.assertFalse(self.page.evaluate("IASDPIPortalAccess.feedRows('2026-11').some(r=>r.id.startsWith('pending:'))"));self.go('schedule-build');self.page.wait_for_selector('.monthly-calendar');self.department('Sonoplastia');self.publish();self.calendar();self.page.wait_for_function("()=>IASDPIPortalAccess.feedRows('2026-11').some(r=>r.id.startsWith('pending:'))")
 def test_same_person_can_be_in_communication_and_sound_same_day(self):
  self.sound();p=self.page.evaluate("""async()=>{const c=await IASDPISchedules.request('iasdpi_schedule_catalog'),d=c.departments.find(d=>d.code==='comunicacao'),role=c.roles.find(r=>r.department_id===d.id&&r.general_assignment),p=c.people.find(p=>p.name==='Gabriel Macedo'),e=await IASDPISchedules.request('iasdpi_schedule_event_create',{p_id:crypto.randomUUID(),p_data:{department_id:d.id,date:'2026-11-07',title:'Atividade fictícia compatível'},p_request_id:crypto.randomUUID()});await IASDPISchedules.request('iasdpi_schedule_plan_save',{p_id:crypto.randomUUID(),p_expected_version:0,p_data:{department_id:d.id,month:'2026-11-01',title:'Comunicação fictícia',status:'published',requirements:[{id:crypto.randomUUID(),event_id:e.id,role_id:role.id,required_count:1,notes:'',assignments:[{id:crypto.randomUUID(),person_id:p.id,timing_mode:'day'}]}]},p_request_id:crypto.randomUUID()});return p.id;}""")
  self.page.locator('[data-b1-action=reload]').click();self.page.wait_for_selector('[data-calendar-volunteer]');field=self.page.locator('.monthly-cell:has([data-day="2026-11-07"]) select').first;self.assertTrue(field.locator('option[value="'+p+'"]').is_enabled());field.select_option(p);self.publish();self.calendar();self.page.wait_for_function("()=>IASDPIPortalAccess.feedRows('2026-11').filter(r=>r.date==='2026-11-07'&&r.person==='Gabriel Macedo').length===2")
 def test_ancionato_can_publish_a_real_unassigned_month(self):
  self.sign_in();self.page.locator('.monthly-departments button').get_by_text('Ancionato',exact=True).click();self.page.wait_for_selector('[data-kind=monthly]');self.page.locator('[data-kind=monthly]').click();self.page.wait_for_selector('.elder-year-calendar');self.page.locator('[data-elder-period="monthly:2026-11-01"] select').select_option('');self.page.once('dialog',lambda d:d.accept());self.page.locator('[data-elder-action=publish]').click();self.page.wait_for_function("()=>document.querySelector('#elder-feedback')?.textContent.includes('Escala publicada')")
  rows=self.page.evaluate("async()=>{const r=await fetch('https://g4demo.supabase.co/rest/v1/rpc/iasdpi_schedule_published',{method:'POST',headers:{'Content-Type':'application/json','x-iasdpi-church':'IASD_PI'},body:JSON.stringify({p_month:'2026-11-01'})});return r.json();}");self.assertTrue(any(r['department']=='Ancionato' and r.get('kind')=='monthly' and r['person']=='' and r['pending'] for r in rows))
 def test_general_event_publishes_directly_without_approval_text(self):
  self.sign_in();self.go('events');self.page.wait_for_selector('[data-event-new]');self.page.locator('[data-event-new]').click();self.page.fill('#event-editor [name=title]','Evento fictício geral publicado');self.page.select_option('#event-editor [name=program_category]','general');self.page.select_option('#event-editor [name=event_organizer]','local_church');self.page.locator('#event-editor button[value=published]').click();self.page.wait_for_function("()=>document.querySelector('#event-save-state')?.textContent.includes('Publicação confirmada')")
  self.assertNotIn('aprovação',self.page.locator('#event-editor').inner_text());self.assertEqual(self.page.locator('#event-approval-status').count(),0)
